import { PriorityQueue } from './src/priority-queue.js';
import { RateLimiter } from './src/rate-limiter.js';
import { ResultCache } from './src/result-cache.js';
import { EventBus } from './src/event-bus.js';
import { Scheduler } from './src/scheduler.js';
import { Pipeline } from './src/pipeline.js';
import { SlidingWindowThrottle } from './src/throttle.js';
import assert from 'node:assert/strict';

let passed = 0;
let failed = 0;
const failures = [];

function test(name, fn) {
  try {
    const result = fn();
    if (result && typeof result.then === 'function') {
      return result.then(() => {
        passed++;
        console.log(`✓ ${name}`);
      }).catch((e) => {
        failed++;
        failures.push({ name, error: e.message || e });
        console.error(`✗ ${name}: ${e.message || e}`);
      });
    }
    passed++;
    console.log(`✓ ${name}`);
  } catch (e) {
    failed++;
    failures.push({ name, error: e.message || e });
    console.error(`✗ ${name}: ${e.message || e}`);
  }
}

async function runTests() {
  // PriorityQueue tests
  test('PQ: pops items in priority order', () => {
    const pq = new PriorityQueue();
    pq.push('low', 10);
    pq.push('high', 1);
    pq.push('mid', 5);
    assert.equal(pq.pop(), 'high');
    assert.equal(pq.pop(), 'mid');
    assert.equal(pq.pop(), 'low');
  });

  test('PQ: maintains heap invariant', () => {
    const pq = new PriorityQueue();
    const items = [7, 3, 9, 1, 5, 8, 2, 6, 4, 10];
    items.forEach((n) => pq.push(`item-${n}`, n));
    const result = [];
    for (let i = 0; !pq.isEmpty(); i++) {
      assert.ok(i < items.length, 'pop() infinite loop');
      result.push(pq.pop());
    }
    const expected = items.sort((a, b) => a - b).map((n) => `item-${n}`);
    assert.deepEqual(result, expected);
  });

  test('PQ: toArray returns sorted items', () => {
    const pq = new PriorityQueue();
    pq.push('z', 9);
    pq.push('a', 1);
    pq.push('m', 5);
    assert.deepEqual(pq.toArray(), ['a', 'm', 'z']);
  });

  test('PQ: merge copies items and preserves heap', () => {
    const pq1 = new PriorityQueue();
    pq1.push('a', 1);
    pq1.push('b', 3);
    const pq2 = new PriorityQueue();
    pq2.push('c', 2);
    pq2.push('d', 4);

    const result = pq1.merge(pq2);
    assert.equal(result, pq1); // returns this
    assert.equal(pq1.size, 4);
    assert.deepEqual(pq1.toArray(), ['a', 'c', 'b', 'd']);

    // pq2 unchanged
    assert.equal(pq2.size, 2);
  });

  // RateLimiter tests
  test('RL: allows burst', () => {
    const limiter = new RateLimiter(10, 5);
    let acquired = 0;
    for (let i = 0; i < 10; i++) {
      if (limiter.tryAcquire()) acquired++;
    }
    assert.equal(acquired, 5);
  });

  test('RL: peekWait returns 0 when available', () => {
    const limiter = new RateLimiter(10, 5);
    assert.equal(limiter.peekWait(1), 0);
    assert.equal(limiter.peekWait(5), 0);
  });

  test('RL: peekWait returns positive wait when unavailable', () => {
    const limiter = new RateLimiter(100, 1);
    limiter.tryAcquire(); // exhaust
    const wait = limiter.peekWait(1);
    assert.ok(wait > 0, `Expected wait > 0, got ${wait}`);
    assert.ok(wait <= 15, `Expected wait <= 15ms, got ${wait}`);
  });

  test('RL: peekWait does not consume tokens', () => {
    const limiter = new RateLimiter(10, 3);
    limiter.peekWait(2);
    assert.ok(limiter.tryAcquire());
  });

  // ResultCache tests
  test('RC: stores and retrieves values', () => {
    const cache = new ResultCache(10, 60000);
    cache.set('key1', { data: 'hello' });
    const result = cache.get('key1');
    assert.deepEqual(result, { data: 'hello' });
  });

  test('RC: returns undefined for missing', () => {
    const cache = new ResultCache();
    assert.equal(cache.get('nope'), undefined);
  });

  test('RC: topKeys returns most accessed', () => {
    const cache = new ResultCache(10, 60000);
    cache.set('a', 1);
    cache.set('b', 2);
    cache.set('c', 3);

    cache.get('a');
    cache.get('a');
    cache.get('a');
    cache.get('b');
    cache.get('b');

    const top = cache.topKeys(2);
    assert.equal(top[0], 'a'); // 3 accesses
    assert.equal(top[1], 'b'); // 2 accesses
  });

  test('RC: topKeys excludes expired', async () => {
    const cache = new ResultCache(10, 30);
    cache.set('a', 1);
    await new Promise((r) => setTimeout(r, 40));
    cache.set('b', 2);

    const top = cache.topKeys(2);
    assert.deepEqual(top, ['b']);
  });

  // EventBus tests
  test('EB: emits events', () => {
    const bus = new EventBus();
    const received = [];
    bus.on('test', (d) => received.push(d));
    bus.emit('test', { value: 1 });
    bus.emit('test', { value: 2 });
    assert.deepEqual(received, [{ value: 1 }, { value: 2 }]);
  });

  test('EB: history respects maxHistory', () => {
    const bus = new EventBus({ maxHistory: 5 });
    for (let i = 0; i < 10; i++) {
      bus.emit('tick', i);
    }
    const h = bus.history(10);
    assert.equal(h.length, 5);
    assert.equal(h[0].data, 9);
    assert.equal(h[4].data, 5);
  });

  // Scheduler tests - async
  await new Promise((resolve) => {
    test('Scheduler: runs tasks in priority order', async () => {
      const order = [];
      const s = new Scheduler({ maxConcurrency: 1 });
      s.add({ id: 'low', fn: () => order.push('low'), priority: 10 });
      s.add({ id: 'high', fn: () => order.push('high'), priority: 1 });
      s.add({ id: 'mid', fn: () => order.push('mid'), priority: 5 });
      await s.run();
      assert.deepEqual(order, ['high', 'mid', 'low']);
    });
    setTimeout(resolve, 100);
  });

  await new Promise((resolve) => {
    test('Scheduler: respects dependencies', async () => {
      const order = [];
      const s = new Scheduler({ maxConcurrency: 4 });
      s.add({ id: 'a', fn: () => order.push('a'), priority: 5 });
      s.add({ id: 'b', fn: () => order.push('b'), priority: 1, deps: ['a'] });
      s.add({ id: 'c', fn: () => order.push('c'), priority: 1, deps: ['b'] });
      await s.run();
      const aIdx = order.indexOf('a');
      const bIdx = order.indexOf('b');
      const cIdx = order.indexOf('c');
      assert.ok(aIdx < bIdx, `a(${aIdx}) before b(${bIdx})`);
      assert.ok(bIdx < cIdx, `b(${bIdx}) before c(${cIdx})`);
    });
    setTimeout(resolve, 200);
  });

  // Throttle tests
  test('Throttle: allows up to maxRequests', () => {
    const t = new SlidingWindowThrottle(3, 1000);
    assert.equal(t.isAllowed('u1', 0), true);
    assert.equal(t.isAllowed('u1', 100), true);
    assert.equal(t.isAllowed('u1', 200), true);
  });

  test('Throttle: blocks exceeding', () => {
    const t = new SlidingWindowThrottle(2, 5000);
    assert.equal(t.isAllowed('u1', 100), true);
    assert.equal(t.isAllowed('u1', 200), true);
    assert.equal(t.isAllowed('u1', 300), false);
  });

  // Wait for async tests
  await new Promise((resolve) => setTimeout(resolve, 500));

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    process.exit(1);
  }
}

runTests().catch(e => {
  console.error('Test error:', e);
  process.exit(1);
});
"}

